def haversine(lat1, lon1, lat2, lon2):
    R = 6371000
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp = math.radians(lat2-lat1)
    dl = math.radians(lon2-lon1)
    a = math.sin(dp/2)**2 + math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(a))

def route_between(a, b):
    mid_lon = (a["lon"] + b["lon"]) / 2
    return [
        [a["lon"], a["lat"]],
        [mid_lon, a["lat"]],
        [mid_lon, b["lat"]],
        [b["lon"], b["lat"]]
    ]

def room_data(floor):
    base_rooms = [
        ["A01","Aula 01","Aula",0,0,24,18,40],
        ["A02","Aula 02","Aula",26,0,50,18,40],
        ["LAB","Laboratorio","Laboratorio",52,0,80,18,30],
        ["OFI","Oficina","Oficina",0,24,20,42,8],
        ["A03","Aula 03","Aula",22,24,47,42,45],
        ["SSHH","SS.HH.","Servicio",49,24,62,42,0],
        ["ESC","Escalera","Circulación",64,24,80,42,0],
    ]
    rows = []
    for code,name,tipo,x0,y0,x1,y1,cap in base_rooms:
        rows.append({
            "codigo": f"{floor}{code}",
            "ambiente": name if floor == 1 else f"{name} - P{floor}",
            "tipo": tipo,
            "x0": x0, "y0": y0, "x1": x1, "y1": y1,
            "capacidad": cap
        })
    return pd.DataFrame(rows)

